use dijkstra::Graph;

#[test]
fn test_simple_path() {
    let mut g = Graph::new(4);
    g.add_edge(0, 1, 1);
    g.add_edge(1, 2, 2);
    g.add_edge(2, 3, 1);
    assert_eq!(g.shortest_path(0, 3), Some(4));
}

#[test]
fn test_shorter_alternative() {
    let mut g = Graph::new(4);
    g.add_edge(0, 1, 10);
    g.add_edge(0, 2, 1);
    g.add_edge(2, 1, 1);
    g.add_edge(1, 3, 1);
    // 0->2->1->3 costs 3, better than 0->1->3 which costs 11
    assert_eq!(g.shortest_path(0, 3), Some(3));
}

#[test]
fn test_unreachable() {
    let mut g = Graph::new(3);
    g.add_edge(0, 1, 5);
    // node 2 is isolated
    assert_eq!(g.shortest_path(0, 2), None);
}

#[test]
fn test_same_node() {
    let g = Graph::new(3);
    assert_eq!(g.shortest_path(1, 1), Some(0));
}

#[test]
fn test_all_distances() {
    let mut g = Graph::new(4);
    g.add_edge(0, 1, 2);
    g.add_edge(0, 2, 4);
    g.add_edge(1, 2, 1);
    g.add_edge(1, 3, 5);
    g.add_edge(2, 3, 1);
    let dists = g.all_shortest_paths(0);
    assert_eq!(dists[0], Some(0));
    assert_eq!(dists[1], Some(2));
    assert_eq!(dists[2], Some(3));
    assert_eq!(dists[3], Some(4));
}

